// Purpose: ROW-023 and ROW-138 (REQ-011) — on the checker page, in every browser of the harness,
// choosing a suggestion replaces only that occurrence, keeps the flagged word's case (Gestion →
// Gestión, GESTION → GESTIÓN, Area → Área), removes that highlight, lowers the count by one and
// leaves every other character unchanged; the list shows each suggestion in the flagged word's case.
// Provenance: generated by tests/invariants/spanish-dictionary.ts (accentPopulation, dictionary-es
// 4.0.0 pinned by SHA-256) and suggestions-population.ts, with a fresh seed per run, plus the rows'
// own examples (Gestion, GESTION, Area); expected texts are the test's own model of the Replace.
//
// Test argument
// ROW-023 promise: choosing a suggestion replaces only that occurrence, keeps its capitalisation
//   (Gestion becomes Gestión), removes its highlight and lowers the count by one, every other
//   character unchanged (REQ-011 fail-if: another occurrence changes, Gestion becomes gestión, any
//   character outside the word changes, or the count does not drop by one; A-018).
// ROW-023 wrong product: a Replace that does text.replace(word, suggestion) — it changes the first
//   textual match, or every match with a global flag — and writes the suggestion as the engine gave
//   it, lower case; or one that redraws the highlights from a fresh count without lowering it.
// ROW-023 given: a fresh accent error s (from the population) written capitalised at the start of the
//   text, the same s written again in lower case later, and a second fresh misspelling t; when: the
//   capitalised one's menu is opened and the suggestion meaning the intended word is chosen; then: the
//   box's text equals the text with ONLY that occurrence replaced by the capitalised intended word,
//   the highlights are exactly the lower-case s and t at their places, and the count's number is one
//   less than before — and before the choice the box held the misspelling and three highlights.
// ROW-023 controls: the capitalised misspelling is highlighted and its menu offers the intended word
//   (in some case) — the path is reached; untouched by a wrong Replace.
// ROW-023 technique: a repeat as decoy (same word twice, one chosen) and whole-text and whole-list
//   comparisons, fresh words per run, the row's own example kept in ROW-138's named set.
// cases: ROW-023 target=ROW-023-replace-changes-only-that-occurrence-keeps-its-capital-and-lowers-the-count control=ROW-023-control-the-capitalised-misspelling-offers-its-intended-word
//
// ROW-138 promise: Replace keeps all-capital and accented-capital forms (GESTION becomes GESTIÓN,
//   Area becomes Área), and the list shows each suggestion in that case (origin: domain; REQ-011
//   "keeping its capitalisation"; A-032 all-capital words of more than 5 letters are checked).
// ROW-138 wrong product: a Replace that capitalises only the first letter (GESTION → Gestión), or
//   one that writes the engine's lower-case suggestion over a capitalised word (Area → área), or a
//   list showing "gestión" for GESTION.
// ROW-138 given: the row's own examples GESTION and Area plus a fresh all-capital accent error and a
//   fresh capitalised error whose intended word starts with an accented vowel, each capitalised one at
//   a sentence start; when: each one's menu is opened and the suggestion meaning its intended word is
//   chosen; then: every suggestion in each menu is written in the flagged word's case, and after the
//   choices the text equals the text with each replaced by the intended word in that case.
// ROW-138 controls: the four words are highlighted and the all-capital one's menu holds a suggestion
//   — the case is reached; untouched by a case fault.
// ROW-138 technique: the row's named examples plus fresh generated ones, exact whole-text comparison.
// cases: ROW-138 target=ROW-138-replace-keeps-all-capital-and-accented-capital-forms-and-the-list-shows-that-case control=ROW-138-control-the-capitalised-words-are-highlighted-and-offer-suggestions

import { expect, test, type Page } from '@playwright/test';
import {
  accentPopulation,
  asActor,
  compose,
  enterOffer,
  freshRandom,
  isDictionaryWord,
  openChecker,
  pressCheck,
  readHighlights,
  type Placed,
  type Rng,
} from './harness';
import { chooseSuggestion, flagsAt, openMenuByPointer, readCount, readMenu, readOfferText, replacedAt } from './suggestions-helpers';

const WAIT_MS = 15_000;
const cap = (w: string) => w.charAt(0).toUpperCase() + w.slice(1);

async function checkAndWait(page: Page, text: string, at: Placed[], row: string, seed: number): Promise<void> {
  await openChecker(page);
  await enterOffer(page, text);
  expect((await pressCheck(page)).status, `${row}: the page's check is answered`).toBe(200);
  await expect
    .poll(async () => {
      const starts = (await flagsAt(page, text)).map((f) => f.start);
      return at.filter((p) => starts.includes(p.start)).length;
    }, { message: `${row}: each placed misspelling is highlighted in ${JSON.stringify(text)} (seed ${seed})`, timeout: WAIT_MS })
    .toBe(at.length);
}

/** The menu's suggestion that means `intended` (compared without case); fails by name when absent. */
async function labelFor(page: Page, intended: string, row: string): Promise<string> {
  const menu = await readMenu(page);
  const label = menu.suggestions.find((s) => s.toLowerCase() === intended.toLowerCase());
  expect(label, `${row}: the menu offers "${intended}" — ${JSON.stringify(menu)}`).toBeTruthy();
  return label!;
}

function pairs(rng: Rng) {
  const pop = accentPopulation().filter((p) => !isDictionaryWord(cap(p.stripped)) && !isDictionaryWord(p.stripped.toUpperCase()));
  const a = rng.pick(pop);
  let b = rng.pick(pop);
  while (b.word === a.word || b.stripped.includes(a.stripped) || a.stripped.includes(b.stripped)) b = rng.pick(pop);
  return { a, b };
}

test('ROW-023-replace-changes-only-that-occurrence-keeps-its-capital-and-lowers-the-count', async ({ page }) => {
  asActor('anonymous');
  const rng = freshRandom();
  const { a, b } = pairs(rng);
  const C = cap(a.stripped); // "Gestion": capitalised, first in its sentence
  const { text, placed } = compose([C, 'para', 'la', 'empresa', 'y', a.stripped, 'del', 'equipo', 'con', b.stripped, 'en', 'la', 'oficina']);
  const pC = placed[0];
  const pLow = placed[5];
  const pT = placed[9];
  await checkAndWait(page, text, [pC, pLow, pT], 'ROW-023', rng.seed);

  const before = await readCount(page);
  expect(before.n, `ROW-023: the count line gives a number after the check — "${before.text}"`).not.toBeNull();
  expect(await readOfferText(page), 'ROW-023: before the choice the box holds the capitalised misspelling').toBe(text);

  await openMenuByPointer(page, text, pC.start, 'ROW-023');
  await chooseSuggestion(page, await labelFor(page, a.word, 'ROW-023'), 'ROW-023');

  const expected = replacedAt(text, pC, cap(a.word));
  await expect
    .poll(() => readOfferText(page), { message: `ROW-023: only the capitalised "${C}" becomes "${cap(a.word)}"; the lower-case "${a.stripped}" and every other character stay (seed ${rng.seed})`, timeout: WAIT_MS })
    .toBe(expected);
  await expect
    .poll(async () => (await readHighlights(page, expected)).map((h) => `${h.word}@${h.start}`), { message: `ROW-023: the replaced word's highlight is gone, the others stay at their places (seed ${rng.seed})`, timeout: WAIT_MS })
    .toEqual([`${a.stripped}@${pLow.start}`, `${b.stripped}@${pT.start}`]);
  await expect
    .poll(async () => (await readCount(page)).n, { message: `ROW-023: the count drops by exactly one, from ${before.n}`, timeout: WAIT_MS })
    .toBe((before.n ?? NaN) - 1);
});

test('ROW-023-control-the-capitalised-misspelling-offers-its-intended-word', async ({ page }) => {
  asActor('anonymous');
  const rng = freshRandom();
  const { a } = pairs(rng);
  const C = cap(a.stripped);
  const { text, placed } = compose([C, 'para', 'la', 'empresa']);
  await checkAndWait(page, text, [placed[0]], 'ROW-023 control', rng.seed);
  await openMenuByPointer(page, text, placed[0].start, 'ROW-023 control');
  await labelFor(page, a.word, 'ROW-023 control');
});

function caseSet(rng: Rng) {
  const pop = accentPopulation();
  const upperPool = pop.filter((p) => !isDictionaryWord(p.stripped.toUpperCase()) && p.word !== 'gestión');
  const initialPool = pop.filter((p) => /^[áéíóú]/.test(p.word) && !/(la|las|lo|los|le|les|me|nos|se|te)$/.test(p.word) && !isDictionaryWord(cap(p.stripped)));
  if (initialPool.length < 5) throw new Error(`setup: only ${initialPool.length} accent-initial words in the population`);
  const u = rng.pick(upperPool);
  const i = rng.pick(initialPool);
  // [what is typed, what the writer means, the case it must keep]
  return [
    { typed: 'Area', intended: 'área', upper: false },
    { typed: 'GESTION', intended: 'gestión', upper: true },
    { typed: cap(i.stripped), intended: i.word, upper: false },
    { typed: u.stripped.toUpperCase(), intended: u.word, upper: true },
  ];
}

function caseText(set: ReturnType<typeof caseSet>) {
  // each capitalised word opens a sentence; the all-capital words stand inside sentences
  return compose(
    [set[0].typed, 'de', 'trabajo', 'con', set[1].typed, 'del', 'equipo', set[2].typed, 'para', 'la', 'empresa', 'y', set[3].typed, 'en', 'la', 'oficina'],
    [' ', ' ', ' ', ' ', ' ', ' ', '. ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' '],
  );
}

const inCase = (s: string, upper: boolean) =>
  upper ? s === s.toUpperCase() && s !== s.toLowerCase() : s.charAt(0) === s.charAt(0).toUpperCase() && s.charAt(0) !== s.charAt(0).toLowerCase() && s.slice(1) === s.slice(1).toLowerCase();

test('ROW-138-replace-keeps-all-capital-and-accented-capital-forms-and-the-list-shows-that-case', async ({ page }) => {
  asActor('anonymous');
  const rng = freshRandom();
  const set = caseSet(rng);
  const { text, placed } = caseText(set);
  const at = [placed[0], placed[4], placed[7], placed[12]];
  await checkAndWait(page, text, at, 'ROW-138', rng.seed);

  let expected = text;
  for (const [k, w] of set.entries()) {
    await openMenuByPointer(page, expected, at[k].start, 'ROW-138');
    const menu = await readMenu(page);
    const outOfCase = menu.suggestions.filter((s) => !inCase(s, w.upper));
    expect(outOfCase, `ROW-138: every suggestion for "${w.typed}" is written ${w.upper ? 'in capitals' : 'with an initial capital'} — ${JSON.stringify(menu.suggestions)}`).toEqual([]);
    const want = w.upper ? w.intended.toUpperCase() : cap(w.intended);
    await chooseSuggestion(page, await labelFor(page, w.intended, 'ROW-138'), 'ROW-138');
    expected = replacedAt(expected, at[k], want);
    await expect
      .poll(() => readOfferText(page), { message: `ROW-138: "${w.typed}" becomes "${want}" and nothing else changes (seed ${rng.seed})`, timeout: WAIT_MS })
      .toBe(expected);
  }
});

test('ROW-138-control-the-capitalised-words-are-highlighted-and-offer-suggestions', async ({ page }) => {
  asActor('anonymous');
  const rng = freshRandom();
  const set = caseSet(rng);
  const { text, placed } = caseText(set);
  const at = [placed[0], placed[4], placed[7], placed[12]];
  await checkAndWait(page, text, at, 'ROW-138 control', rng.seed);
  await openMenuByPointer(page, text, at[1].start, 'ROW-138 control');
  expect((await readMenu(page)).suggestions.length, 'ROW-138 control: GESTION\'s menu holds a suggestion').toBeGreaterThan(0);
});
